// taskNameCleaner 攻城任务名清洗：去掉常见的攻打/城池等前后缀词，提取纯城池名
var taskNameCleaner = []string{"攻城", "拿下", "占领", "攻打", "进攻", "打", "目标", "奖励", "集结", "备战", "清除", "防守", "州府", "郡城", "县城", "城池", "（", "）", "(", ")", "，", ",", "、", " ", "　"}

// extractCityFromTaskName 从攻城任务名提取城池名，提取结果需通过城池名单校验才有效
func extractCityFromTaskName(name string) string {
	name = strings.TrimSpace(name)
	for _, kw := range taskNameCleaner {
		name = strings.ReplaceAll(name, kw, "")
	}
	return strings.TrimSpace(name)
}